#!/usr/bin/env python3
"""Run and compare the frozen representative Theme fixed-plan execution cells."""

# Some portions generated by Codex

from __future__ import annotations

import argparse
import hashlib
import itertools
import json
import math
import pathlib
import statistics
import subprocess
import sys
from collections.abc import Sequence
from typing import Any


THEMES = (
    "MEDICAL_RECORDS",
    "SOCIAL_MEDIA",
    "LIBRARY",
    "ENGINEERING",
    "HIGHLY_CONNECTED",
    "TRAIN",
    "ELECTRICAL_GRID",
    "PHARMA",
    "SPARSE",
)
SAFE_CELLS = (
    ("SOCIAL_MEDIA", 4),
    ("SOCIAL_MEDIA", 9),
    ("MEDICAL_RECORDS", 9),
    ("MEDICAL_RECORDS", 10),
    ("HIGHLY_CONNECTED", 10),
    ("LIBRARY", 10),
)
BENCHMARK = "org.eclipse.rdf4j.sail.lmdb.benchmark.ThemeQueryPlanRunBenchmark.runQuery"
FIXED_PROPERTY = "-Drdf4j.benchmark.themeQueryPlanRun.planLifecycle=FIXED"


def parse_cell(value: str) -> tuple[str, int]:
    theme, separator, query_text = value.partition(":")
    if not separator or theme not in THEMES:
        raise argparse.ArgumentTypeError("cell must be THEME:QUERY with a known Theme")
    try:
        query = int(query_text)
    except ValueError as failure:
        raise argparse.ArgumentTypeError("cell query index must be an integer") from failure
    if query < 0 or query > 12:
        raise argparse.ArgumentTypeError("cell query index must be in [0,12]")
    return theme, query


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--jar", type=pathlib.Path, required=True)
    parser.add_argument("--store-root", type=pathlib.Path, required=True)
    parser.add_argument("--results", type=pathlib.Path, required=True)
    parser.add_argument("--summary", type=pathlib.Path, required=True)
    parser.add_argument("--baseline-summary", type=pathlib.Path)
    parser.add_argument("--timeout-seconds", type=float, default=390.0)
    parser.add_argument("--termination-grace-seconds", type=float, default=5.0)
    parser.add_argument("--warmups", type=int, default=1)
    parser.add_argument("--measurements", type=int, default=5)
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--cell", action="append", type=parse_cell)
    parser.add_argument("--max-cells", type=int)
    args = parser.parse_args()
    if (
        args.timeout_seconds <= 0
        or args.termination_grace_seconds < 0
        or args.warmups < 0
        or args.measurements <= 0
        or (args.max_cells is not None and args.max_cells < 0)
    ):
        parser.error("timeouts/counts must be positive and optional limits non-negative")
    if not args.jar.is_file():
        parser.error(f"benchmark jar does not exist: {args.jar}")
    if not args.store_root.is_dir():
        parser.error(f"store root does not exist: {args.store_root}")
    if args.baseline_summary is not None and not args.baseline_summary.is_file():
        parser.error(f"baseline summary does not exist: {args.baseline_summary}")
    return args


def digest(path: pathlib.Path) -> str | None:
    if not path.is_file():
        return None
    value = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def read_json(path: pathlib.Path) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None


def write_json(path: pathlib.Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    temporary.replace(path)


def cell_id(theme: str, query: int) -> str:
    return f"{theme.lower()}-q{query}"


def result_path(results: pathlib.Path, theme: str, query: int) -> pathlib.Path:
    return results / f"{cell_id(theme, query)}.json"


def status_path(result: pathlib.Path) -> pathlib.Path:
    return result.with_suffix(".status.json")


def stdout_path(result: pathlib.Path) -> pathlib.Path:
    return result.with_suffix(".stdout.log")


def stderr_path(result: pathlib.Path) -> pathlib.Path:
    return result.with_suffix(".stderr.log")


def outcome(result: pathlib.Path) -> str | None:
    status = read_json(status_path(result))
    return status.get("outcome") if isinstance(status, dict) else None


def jmh_entry(
    result: pathlib.Path,
    theme: str,
    query: int,
    warmups: int,
    measurements: int,
) -> dict[str, Any] | None:
    value = read_json(result)
    if outcome(result) != "succeeded" or not isinstance(value, list) or len(value) != 1:
        return None
    entry = value[0]
    jvm_args = entry.get("jvmArgs") if isinstance(entry, dict) else None
    if (
        not isinstance(entry, dict)
        or entry.get("benchmark") != BENCHMARK
        or entry.get("mode") != "ss"
        or entry.get("threads") != 1
        or entry.get("forks") != 1
        or entry.get("warmupIterations") != warmups
        or entry.get("measurementIterations") != measurements
        or entry.get("params") != {"themeName": theme, "z_queryIndex": str(query)}
        or not isinstance(jvm_args, list)
        or FIXED_PROPERTY not in jvm_args
    ):
        return None
    return entry


def raw_samples(metric: dict[str, Any]) -> list[float]:
    raw = metric.get("rawData")
    if not isinstance(raw, list):
        raise ValueError("JMH metric has no rawData")
    samples: list[float] = []
    for fork in raw:
        if not isinstance(fork, list):
            raise ValueError("JMH rawData fork is not a list")
        for sample in fork:
            if not isinstance(sample, (int, float)) or not math.isfinite(sample) or sample < 0:
                raise ValueError("JMH rawData contains an invalid sample")
            samples.append(float(sample))
    if not samples:
        raise ValueError("JMH metric has no samples")
    return samples


def percentile_nearest_rank(values: Sequence[float], percentile: float) -> float:
    ordered = sorted(values)
    if not ordered:
        raise ValueError("percentile requires samples")
    rank = max(1, math.ceil(percentile * len(ordered)))
    return ordered[rank - 1]


def entry_measurement(entry: dict[str, Any], theme: str, query: int) -> dict[str, Any]:
    primary = entry.get("primaryMetric")
    secondary = entry.get("secondaryMetrics")
    if not isinstance(primary, dict) or not isinstance(secondary, dict):
        raise ValueError("JMH entry lacks primary or secondary metrics")
    allocation_metric = secondary.get("gc.alloc.rate.norm")
    if not isinstance(allocation_metric, dict):
        raise ValueError("JMH entry lacks normalized allocation")
    times = raw_samples(primary)
    allocations = raw_samples(allocation_metric)
    if len(times) != len(allocations):
        raise ValueError("time and allocation sample counts differ")
    return {
        "theme": theme,
        "queryIndex": query,
        "status": "complete",
        "issues": [],
        "sampleCount": len(times),
        "medianMillis": statistics.median(times),
        "p95Millis": percentile_nearest_rank(times, 0.95),
        "medianAllocationBytes": statistics.median(allocations),
        "p95AllocationBytes": percentile_nearest_rank(allocations, 0.95),
        "rawMillis": times,
        "rawAllocationBytes": allocations,
    }


def summarize_campaign(
    results: pathlib.Path,
    cells: Sequence[tuple[str, int]],
    warmups: int,
    measurements: int,
) -> dict[str, Any]:
    records: list[dict[str, Any]] = []
    for theme, query in cells:
        result = result_path(results, theme, query)
        entry = jmh_entry(result, theme, query, warmups, measurements)
        result_outcome = outcome(result)
        if entry is None:
            if result_outcome in {"timeout", "failed"}:
                issue = f"jmh-{result_outcome}"
            elif result_outcome is None and not result.exists():
                issue = "jmh-missing"
            else:
                issue = "jmh-stale"
            records.append(
                {
                    "theme": theme,
                    "queryIndex": query,
                    "status": "incomplete",
                    "issues": [issue],
                }
            )
            continue
        try:
            records.append(entry_measurement(entry, theme, query))
        except ValueError as failure:
            records.append(
                {
                    "theme": theme,
                    "queryIndex": query,
                    "status": "incomplete",
                    "issues": [f"jmh-invalid:{failure}"],
                }
            )
    complete_count = sum(record["status"] == "complete" for record in records)
    return {
        "formatVersion": 1,
        "status": "complete" if complete_count == len(cells) and cells else "incomplete",
        "planLifecycle": "FIXED",
        "expectedCellCount": len(cells),
        "completeCellCount": complete_count,
        "cells": records,
    }


def u_statistic(first: Sequence[float], second: Sequence[float]) -> float:
    return sum(
        1.0 if left > right else 0.5 if left == right else 0.0
        for left in first
        for right in second
    )


def exact_one_sided_p_values(baseline: Sequence[float], candidate: Sequence[float]) -> tuple[float, float]:
    combined = tuple(baseline) + tuple(candidate)
    candidate_size = len(candidate)
    observed = u_statistic(candidate, baseline)
    at_least = 0
    at_most = 0
    total = 0
    indexes = range(len(combined))
    for candidate_indexes in itertools.combinations(indexes, candidate_size):
        selected = set(candidate_indexes)
        permuted_candidate = [combined[index] for index in indexes if index in selected]
        permuted_baseline = [combined[index] for index in indexes if index not in selected]
        statistic = u_statistic(permuted_candidate, permuted_baseline)
        at_least += statistic >= observed
        at_most += statistic <= observed
        total += 1
    return at_least / total, at_most / total


def complete_cell_map(summary: dict[str, Any]) -> dict[tuple[str, int], dict[str, Any]]:
    cells = summary.get("cells")
    if not isinstance(cells, list):
        return {}
    return {
        (cell["theme"], cell["queryIndex"]): cell
        for cell in cells
        if isinstance(cell, dict)
        and cell.get("status") == "complete"
        and isinstance(cell.get("theme"), str)
        and isinstance(cell.get("queryIndex"), int)
    }


def compare_summaries(baseline: dict[str, Any], candidate: dict[str, Any]) -> dict[str, Any]:
    baseline_cells = complete_cell_map(baseline)
    candidate_cells = complete_cell_map(candidate)
    keys = sorted(set(baseline_cells) | set(candidate_cells))
    records = []
    observed_regressions = 0
    significant_regressions = 0
    for key in keys:
        baseline_cell = baseline_cells.get(key)
        candidate_cell = candidate_cells.get(key)
        if baseline_cell is None or candidate_cell is None:
            records.append(
                {
                    "theme": key[0],
                    "queryIndex": key[1],
                    "status": "incomplete",
                    "classification": "unmatched",
                }
            )
            continue
        baseline_samples = baseline_cell["rawMillis"]
        candidate_samples = candidate_cell["rawMillis"]
        regression_p, improvement_p = exact_one_sided_p_values(
            baseline_samples, candidate_samples
        )
        baseline_median = float(baseline_cell["medianMillis"])
        candidate_median = float(candidate_cell["medianMillis"])
        ratio = candidate_median / baseline_median
        if candidate_median > baseline_median:
            observed_regressions += 1
        if candidate_median > baseline_median and regression_p <= 0.05:
            classification = "regression"
            significant_regressions += 1
        elif candidate_median < baseline_median and improvement_p <= 0.05:
            classification = "improvement"
        else:
            classification = "inconclusive"
        records.append(
            {
                "theme": key[0],
                "queryIndex": key[1],
                "status": "complete",
                "classification": classification,
                "baselineMedianMillis": baseline_median,
                "candidateMedianMillis": candidate_median,
                "candidateToBaselineMedianRatio": ratio,
                "oneSidedRegressionPValue": regression_p,
                "oneSidedImprovementPValue": improvement_p,
            }
        )
    complete = (
        baseline.get("status") == "complete"
        and candidate.get("status") == "complete"
        and bool(keys)
        and all(record["status"] == "complete" for record in records)
    )
    strict_pass = complete and observed_regressions == 0
    return {
        "formatVersion": 1,
        "status": "complete" if complete else "incomplete",
        "fixedPlanExecutionRegressionAllowed": False,
        "observedMedianRegressionCellCount": observed_regressions,
        "significantRegressionCellCount": significant_regressions,
        "observedMedianNoRegressionPass": strict_pass,
        "significantRegressionAbsent": complete and significant_regressions == 0,
        "acceptancePass": strict_pass,
        "cells": records,
    }


def jmh_command(args: argparse.Namespace, theme: str, query: int, result: pathlib.Path) -> list[str]:
    command = [
        "java",
        "-jar",
        str(args.jar.resolve()),
        f"^{BENCHMARK}$",
        "-p",
        f"themeName={theme}",
        "-p",
        f"z_queryIndex={query}",
        "-wi",
        str(args.warmups),
        "-i",
        str(args.measurements),
        "-f",
        "1",
        "-t",
        "1",
        "-bm",
        "ss",
        "-tu",
        "ms",
        "-to",
        "60s",
        "-prof",
        "gc",
        "-rf",
        "json",
        "-rff",
        str(result.resolve()),
    ]
    for argument in (
        "--enable-native-access=ALL-UNNAMED",
        f"-Drdf4j.test.outputDirectory={args.store_root.resolve()}",
        "-Drdf4j.benchmark.profiling=true",
        FIXED_PROPERTY,
    ):
        command.extend(("-jvmArgsAppend", argument))
    return command


def run_supervised(
    args: argparse.Namespace,
    repo_root: pathlib.Path,
    command: Sequence[str],
    result: pathlib.Path,
) -> int:
    result.parent.mkdir(parents=True, exist_ok=True)
    supervisor = [
        sys.executable,
        str((repo_root / "scripts/run-supervised-process.py").resolve()),
        "--timeout-seconds",
        str(args.timeout_seconds),
        "--termination-grace-seconds",
        str(args.termination_grace_seconds),
        "--status",
        str(status_path(result).resolve()),
        "--stdout",
        str(stdout_path(result).resolve()),
        "--stderr",
        str(stderr_path(result).resolve()),
        "--",
        *command,
    ]
    return subprocess.run(supervisor, cwd=repo_root, check=False).returncode


def write_index(args: argparse.Namespace, cells: Sequence[tuple[str, int]]) -> None:
    write_json(
        args.results / "campaign-index.json",
        {
            "formatVersion": 1,
            "jar": str(args.jar.resolve()),
            "jarSha256": digest(args.jar),
            "storeRoot": str(args.store_root.resolve()),
            "planLifecycle": "FIXED",
            "warmups": args.warmups,
            "measurements": args.measurements,
            "externalTimeoutSeconds": args.timeout_seconds,
            "cells": [
                {
                    "theme": theme,
                    "queryIndex": query,
                    "outcome": outcome(result_path(args.results, theme, query)) or "missing",
                    "resultSha256": digest(result_path(args.results, theme, query)),
                    "statusSha256": digest(status_path(result_path(args.results, theme, query))),
                }
                for theme, query in cells
            ],
        },
    )


def campaign_summary(args: argparse.Namespace, cells: Sequence[tuple[str, int]]) -> dict[str, Any]:
    summary = summarize_campaign(args.results, cells, args.warmups, args.measurements)
    summary["jar"] = str(args.jar.resolve())
    summary["jarSha256"] = digest(args.jar)
    summary["storeRoot"] = str(args.store_root.resolve())
    if args.baseline_summary is not None:
        baseline = read_json(args.baseline_summary)
        if isinstance(baseline, dict):
            summary["comparison"] = compare_summaries(baseline, summary)
        else:
            summary["comparison"] = {"status": "incomplete", "acceptancePass": False}
    return summary


def persist(args: argparse.Namespace, cells: Sequence[tuple[str, int]]) -> None:
    write_index(args, cells)
    write_json(args.summary, campaign_summary(args, cells))


def main() -> int:
    args = parse_args()
    repo_root = pathlib.Path(__file__).resolve().parents[1]
    cells = tuple(args.cell or SAFE_CELLS)
    if args.max_cells is not None:
        cells = cells[: args.max_cells]
    args.results.mkdir(parents=True, exist_ok=True)
    persist(args, cells)
    for theme, query in cells:
        result = result_path(args.results, theme, query)
        if args.resume and jmh_entry(result, theme, query, args.warmups, args.measurements) is not None:
            print(f"[fixed-execution] retained {cell_id(theme, query)}", flush=True)
        else:
            print(f"[fixed-execution] running {cell_id(theme, query)}", flush=True)
            exit_code = run_supervised(args, repo_root, jmh_command(args, theme, query, result), result)
            print(
                f"[fixed-execution] {cell_id(theme, query)}: {outcome(result) or 'missing'} "
                f"(exit {exit_code})",
                flush=True,
            )
        persist(args, cells)
    summary = campaign_summary(args, cells)
    write_json(args.summary, summary)
    write_index(args, cells)
    if summary["status"] != "complete":
        return 1
    comparison = summary.get("comparison")
    return 0 if not isinstance(comparison, dict) or comparison.get("acceptancePass") is True else 1


if __name__ == "__main__":
    sys.exit(main())
